export const meta = {
  name: 'demo-wave',
  description: "Implementa e verifica a onda",
  phases: [
    { title: 'Implementar', detail: "Um agente por tarefa" },
    { title: `Verificar` },
  ],
}

export default async function run(ctx, args) {
  const report = await ctx.agent({ label: 'impl:A', phase: 'Implementar', prompt: `Implemente a tarefa ${args.task}.` })
  return ctx.agent({ label: 'verify:A#1', phase: 'Verificar', prompt: 'Verifique a tarefa A.', schema: { passed: 'boolean' } })
}

